# ── FP: float32 table — scene, camera, constants, scratch (offsets are generated)
#@FP@
# 16:9 monitor showing the 4:3 picture stretched: pixels are 4/3 wider than tall.
# 1 = widen each pixel's horizontal ray angle by 4/3 (same vertical view, wider
# horizontal view) so circles stay round on that monitor. 0 = square pixels (4:3 display).
WIDE_PIXELS = const(1)
if WIDE_PIXELS:
    FP[O_U0 // 4] *= 4 / 3
    FP[O_DU // 4] *= 4 / 3

# Screen projection for splatted points (stars, sparks): column = x/z * IDU + IU0, row = JV0 - y/z * IDV
FP[O_IDU // 4] = 1 / FP[O_DU // 4]
FP[O_IU0 // 4] = -FP[O_U0 // 4] / FP[O_DU // 4]
FP[O_IDV // 4] = 1 / FP[O_DV // 4]
FP[O_JV0 // 4] = FP[O_V0 // 4] / FP[O_DV // 4]

# Edge anti-aliasing: coverage scale per object from the final pixel footprint.
_du = (FP[O_DU // 4] + FP[O_DV // 4]) / 2
FP[O_KORBF // 4] = 1 / (2 * 0.30 * _du)     # orb radius loose
FP[O_KORBH // 4] = 1 / (2 * 0.15 * _du)     # orb radius while carried
FP[O_KORB // 4] = FP[O_KORBH // 4]
FP[O_KROT // 4] = 1 / (2 * _du * FP[O_IRY // 4])
FP[O_KPOST // 4] = 1 / (2 * sqrt(FP[O_PR2 // 4]) * _du)

