PALETTE = const(0)          # palette at power-up
AMBIENT = 0.22              # floor ambient; matches AMB in gen_rt.py

def _pal(p):                # palette -> (FP index, value) pairs, derived terms included
    top, hor, ta, tb, oe, oc, tint, acc, post, gloss, wall, feat = PALETTES[p]
    lit = AMBIENT + (1 - AMBIENT) * FP[O_LX // 4 + 1]
    ta = [c * lit for c in ta]
    tb = [c * lit for c in tb]
    g = [(e + c) / 2 for e, c in zip(oe, oc)]
    out = []
    for o, vals in ((O_TA, ta), (O_TB, tb), (O_DT, [b - a for a, b in zip(ta, tb)]),
                    (O_HOR, hor), (O_DH, [t - h for t, h in zip(top, hor)]),
                    (O_OE, oe), (O_OD, [c - e for c, e in zip(oc, oe)]), (O_OCORE, oc),
                    (O_GLOW, g), (O_OLIGHT, [c * 0.9 for c in g]),
                    (O_TINT, tint), (O_RIM, [c * 0.6 for c in acc]), (O_STRIPE, [c * 1.4 for c in acc]),
                    (O_MREF, [t * (0.5 * (a + b) + h) * 0.6 for t, a, b, h in zip(tint, ta, tb, hor)]),
                    (O_POSTC, post), (O_POSTREF, [c * 0.8 for c in post]),
                    (O_RSIL, [t * h + 0.6 * c for t, h, c in zip(tint, hor, acc)]),
                    (O_FR0, [0.10 * gloss]), (O_FR1, [0.65 * gloss]),
                    (O_WC, wall), (O_FEATF, [float(feat)])):
        for k, x in enumerate(vals):
            out.append((o // 4 + k, x))
    return out

